import React from 'react';
import { HelpCircle, Lock, Store } from 'lucide-react';

interface ListingFaq {
  question: string;
  answer: string;
}

interface WidgetProps {
  type: string;
  listing: {
    metadata?: {
      faqs?: unknown;
    };
  };
}

const listingFaqs = (value: unknown): ListingFaq[] => {
  if (!Array.isArray(value)) return [];
  return value.flatMap((entry) => {
    if (!entry || typeof entry !== 'object') return [];
    const record = entry as Record<string, unknown>;
    const question = typeof record.question === 'string' ? record.question.trim() : '';
    const answer = typeof record.answer === 'string' ? record.answer.trim() : '';
    return question && answer ? [{ question, answer }] : [];
  });
};

export const ListingWidgets: React.FC<WidgetProps> = ({ type, listing }) => {
  if (type === 'trust_badges') {
    return (
      <div className="grid grid-cols-1 gap-4 rounded-3xl border border-white/10 bg-white/5 p-6 sm:grid-cols-2">
        <div className="flex items-center gap-3">
          <Lock className="h-6 w-6 text-indigo-400" />
          <div>
            <p className="text-sm font-bold text-white">Secure checkout</p>
            <p className="text-xs text-gray-400">Payment details are handled by Stripe.</p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <Store className="h-6 w-6 text-indigo-400" />
          <div>
            <p className="text-sm font-bold text-white">Seller details</p>
            <p className="text-xs text-gray-400">Review the seller and listing terms before buying.</p>
          </div>
        </div>
      </div>
    );
  }

  if (type === 'faq') {
    const faqs = listingFaqs(listing.metadata?.faqs);
    if (faqs.length === 0) return null;
    return (
      <section className="space-y-4" aria-labelledby="listing-faq-heading">
        <h3 id="listing-faq-heading" className="flex items-center gap-2 text-xl font-bold text-white">
          <HelpCircle className="h-5 w-5 text-indigo-300" />
          Frequently asked questions
        </h3>
        <div className="space-y-2">
          {faqs.map((item) => (
            <details key={item.question} className="rounded-2xl border border-white/10 bg-white/5 p-4">
              <summary className="cursor-pointer text-sm font-bold text-white">{item.question}</summary>
              <p className="mt-2 text-xs leading-5 text-gray-400">{item.answer}</p>
            </details>
          ))}
        </div>
      </section>
    );
  }

  // Countdown, social-proof and newsletter widgets require real persisted
  // configuration and data. Hidden legacy widgets must never invent it.
  return null;
};
